// Administration screens: staff, devices, organisation, posts & checkpoints, roles & access, settings, privacy, audit, account, platform.
import { useState } from 'react';
import { del, get, newKey, patch, post, put, qs } from './api.ts';
import { AsOf, Async, Chip, type FieldDef, Form, FormModal, KV, Modal, Num, Page, ReasonModal, Secret, Table, Tabs, When, useAct, useApp, useLoad } from './ui.tsx';

const unitOptions = (u: any[] | undefined) => (u ?? []).map((x) => ({ value: x.id, label: `${'· '.repeat(x.depth)}${x.name}` }));

export function Staff({ live }: { live: number }) {
  const { t, can } = useApp(); const act = useAct();
  const [f, setF] = useState({ q: '', status: '', unitId: '' }); const [dlg, setDlg] = useState<any>(null); const [sel, setSel] = useState<string | null>(null);
  const s = useLoad<any>(`/staff${qs({ ...f, limit: 200 })}`, [live]); const units = useLoad<any>('/units'); const roles = useLoad<any>(can('role.read') ? '/roles' : null);
  const d = useLoad<any>(sel ? `/staff/${sel}` : null, [live]); const sum = useLoad<any>(sel ? `/staff/${sel}/summary` : null);
  return <Page title={t('nav.staff')} actions={<>{can('staff.import') && <button onClick={() => setDlg({ kind: 'import' })}>{t('staff.import')}</button>}{can('staff.create') && <button className="primary" onClick={() => setDlg({ kind: 'add' })}>{t('staff.add')}</button>}</>}>
    <div className="filters"><div className="field"><label htmlFor="sf-q">{t('common.search')}</label><input id="sf-q" value={f.q} onChange={(e: any) => setF({ ...f, q: e.target.value })} /></div>
      <div className="field"><label htmlFor="sf-s">{t('common.status')}</label><select id="sf-s" value={f.status} onChange={(e: any) => setF({ ...f, status: e.target.value })}><option value="">{t('common.all')}</option>{['invited', 'active', 'suspended', 'offboarded'].map((x) => <option key={x} value={x}>{t(`staff.${x}`)}</option>)}</select></div>
      <div className="field"><label htmlFor="sf-u">{t('common.unit')}</label><select id="sf-u" value={f.unitId} onChange={(e: any) => setF({ ...f, unitId: e.target.value })}><option value="">{t('common.all')}</option>{unitOptions(units.data?.items).map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select></div></div>
    <div className="grid two"><Async s={s}><Table caption={t('nav.staff')} rows={s.data?.items ?? []} selected={sel} onRow={(r) => setSel(r.id)} cols={[{ key: 'employeeCode', label: t('staff.employeeCode'), render: (r) => <span className="mono">{r.employeeCode}</span> }, { key: 'displayName', label: t('staff.displayName') }, { key: 'rankTitle', label: t('staff.rank') }, { key: 'u', label: t('staff.homeUnit'), render: (r) => units.data?.items.find((u: any) => u.id === r.homeUnitId)?.name ?? '—' }, { key: 'status', label: t('common.status'), render: (r) => <Chip value={r.status} ns="staff" /> }]} /></Async>
      {sel && <Async s={d}>{d.data && <div className="card"><h2>{d.data.displayName}</h2>
        <KV items={[[t('staff.employeeCode'), <span className="mono">{d.data.employeeCode}</span>], [t('common.status'), <Chip value={d.data.status} ns="staff" />], [t('staff.rank'), d.data.rankTitle], [t('staff.phone'), d.data.contactMasked ? <i>{t('staff.masked')}</i> : d.data.contact?.phone], [t('staff.email'), d.data.contactMasked ? <i>{t('staff.masked')}</i> : d.data.contact?.email], [t('staff.role'), (roles.data?.items ?? []).filter((r: any) => d.data.roleIds.includes(r.id)).map((r: any) => r.name).join(', ')]]} />
        <div className="row" style={{ marginTop: 10 }}>
          {can('staff.invite') && ['invited', 'active'].includes(d.data.status) && <button onClick={() => void act(async () => setDlg({ kind: 'code', name: d.data.displayName, r: await post(`/staff/${sel}/invitation`, { channel: 'code' }) }))}>{t('staff.invite')}</button>}
          {can('staff.update') && <button onClick={() => setDlg({ kind: 'edit', s: d.data })}>{t('common.edit')}</button>}
          {can('staff.lifecycle') && d.data.status === 'active' && <button onClick={() => setDlg({ kind: 'life', action: 'suspend' })}>{t('staff.suspend')}</button>}
          {can('staff.lifecycle') && d.data.status === 'suspended' && <button onClick={() => setDlg({ kind: 'life', action: 'reinstate' })}>{t('staff.reinstate')}</button>}
          {can('staff.lifecycle') && d.data.status !== 'offboarded' && <button className="danger" onClick={() => setDlg({ kind: 'life', action: 'offboard' })}>{t('staff.offboard')}</button>}
          {can('membership.update') && d.data.membershipId && <button onClick={() => setDlg({ kind: 'access', s: d.data })}>{t('role.changeAccess')}</button>}
          {can('privacy.subject.manage') && <button onClick={() => setDlg({ kind: 'export' })}>{t('prv.exportSubject')}</button>}
          {can('privacy.subject.manage') && d.data.status === 'offboarded' && <button className="danger" onClick={() => setDlg({ kind: 'delete' })}>{t('prv.deleteSubject')}</button>}
        </div>
        {sum.data && <><h3 style={{ marginTop: 14 }}>{t('plan.assignments')}</h3><Table caption={t('plan.assignments')} rows={sum.data.assignments.slice(0, 10)} onRow={(r) => { location.hash = `#/attendance/${r.id}`; }} cols={[{ key: 'localDate', label: t('plan.date') }, { key: 'shiftName', label: t('plan.shifts') }, { key: 'status', label: t('common.status'), render: (r) => <Chip value={r.status} ns="duty" /> }]} /></>}
      </div>}</Async>}</div>
    {dlg?.kind === 'add' && <FormModal title={t('staff.add')} onClose={() => setDlg(null)} fields={[{ name: 'employeeCode', label: t('staff.employeeCode'), required: true, ltr: true }, { name: 'displayName', label: t('staff.displayName'), required: true }, { name: 'rankTitle', label: t('staff.rank') }, { name: 'homeUnitId', label: t('staff.homeUnit'), type: 'select', required: true, options: unitOptions(units.data?.items) },
      { name: 'roleId', label: t('staff.role'), type: 'select', options: (roles.data?.items ?? []).filter((r: any) => r.key !== 'owner').map((r: any) => ({ value: r.id, label: r.name })), help: 'Default: Field Staff Member' }, { name: 'email', label: t('staff.email'), type: 'email', ltr: true }, { name: 'phone', label: t('staff.phone'), ltr: true }]}
      onSubmit={async (v) => { const { roleId, ...rest } = v; const r = await post('/staff', { ...rest, ...(roleId ? { roleIds: [roleId] } : {}) }); setDlg(null); s.reload(); setSel(r.id); }} />}
    {dlg?.kind === 'edit' && <FormModal title={t('common.edit')} onClose={() => setDlg(null)} initial={{ displayName: dlg.s.displayName, rankTitle: dlg.s.rankTitle ?? '', homeUnitId: dlg.s.homeUnitId, phone: dlg.s.contact?.phone ?? '', email: dlg.s.contact?.email ?? '' }} fields={[{ name: 'displayName', label: t('staff.displayName'), required: true }, { name: 'rankTitle', label: t('staff.rank') }, { name: 'homeUnitId', label: t('staff.homeUnit'), type: 'select', options: unitOptions(units.data?.items) }, { name: 'email', label: t('staff.email'), type: 'email', ltr: true }, { name: 'phone', label: t('staff.phone'), ltr: true }]}
      onSubmit={async (v) => { await patch(`/staff/${sel}`, { version: dlg.s.version, ...v }); setDlg(null); d.reload(); s.reload(); }} />}
    {dlg?.kind === 'access' && <ReasonModal title={t('role.changeAccess')} onClose={() => setDlg(null)} extra={[{ name: 'roleId', label: t('staff.role'), type: 'select', required: true, options: (roles.data?.items ?? []).filter((r: any) => r.key !== 'owner').map((r: any) => ({ value: r.id, label: r.name })) }, { name: 'scope', label: t('role.scope'), type: 'select', required: true, options: [{ value: '*', label: t('role.wholeOrg') }, ...unitOptions(units.data?.items)] }]}
      onSubmit={async (v) => { await patch(`/memberships/${dlg.s.membershipId}`, { version: dlg.s.membershipVersion, roleIds: [v.roleId], scopeUnitIds: [v.scope], reason: v.reason }); setDlg(null); d.reload(); }} />}
    {dlg?.kind === 'life' && <ReasonModal danger={dlg.action === 'offboard'} title={t(`staff.${dlg.action}`)} intro={dlg.action !== 'reinstate' && <p className="notice warn">{t('staff.offboardEffects')}</p>} onClose={() => setDlg(null)} onSubmit={async (v) => { await post(`/staff/${sel}/${dlg.action}`, v); setDlg(null); d.reload(); s.reload(); }} />}
    {dlg?.kind === 'code' && <Modal title={t('staff.activationFor', { name: dlg.name })} onClose={() => setDlg(null)}><KV items={[[t('staff.username'), <span className="mono">{dlg.r.username}</span>], ['Expires', <When at={dlg.r.expiresAt} />]]} /><Secret label={t('auth.activationCode')} value={dlg.r.activationCode} /><div className="row end"><button onClick={() => setDlg(null)}>{t('common.close')}</button></div></Modal>}
    {dlg?.kind === 'import' && <ImportModal onClose={() => { setDlg(null); s.reload(); }} />}
    {dlg?.kind === 'export' && <ReasonModal title={t('prv.exportSubject')} onClose={() => setDlg(null)} onSubmit={async (v) => { const r = await post(`/staff/${sel}/data-export`, v); setDlg(null); window.location.href = r.download.url; }} />}
    {dlg?.kind === 'delete' && <ReasonModal danger title={t('prv.deleteSubject')} onClose={() => setDlg(null)} onSubmit={async (v) => { const dry = await post(`/staff/${sel}/data-deletion`, { ...v, dryRun: true }); if (!confirm(JSON.stringify(dry.wouldDelete))) return; await post(`/staff/${sel}/data-deletion`, v); setDlg(null); d.reload(); }} />}
  </Page>;
}
function ImportModal({ onClose }: { onClose(): void }) {
  const { t } = useApp(); const [csv, setCsv] = useState(''); const [res, setRes] = useState<any>(null); const act = useAct();
  return <Modal title={t('staff.import')} onClose={onClose} wide><p className="small muted">{t('staff.importHelp')}</p>
    <div className="field"><label htmlFor="imp-f">CSV</label><input id="imp-f" type="file" accept=".csv,text/csv" onChange={(e: any) => { const file = e.target.files?.[0]; if (file) void file.text().then((x: string) => { setCsv(x); setRes(null); }); }} /></div>
    <div className="row"><button disabled={!csv} onClick={() => void act(async () => setRes(await post('/staff/import/dry-run', { csv })))}>{t('staff.dryRun')}</button><button className="primary" disabled={!res || !res.summary.valid || res.done} onClick={() => void act(async () => setRes({ ...(await post('/staff/import', { csv })), done: true }))}>{t('staff.runImport')}</button></div>
    {res && <><p><b>{JSON.stringify(res.summary)}</b></p><Table caption={t('staff.import')} rowKey="row" rows={res.report} cols={[{ key: 'row', label: '#' }, { key: 'employeeCode', label: t('staff.employeeCode') }, { key: 'status', label: t('common.status') }, { key: 'reasons', label: t('common.reason'), render: (r) => r.reasons.join('; ') }]} /></>}
  </Modal>;
}

export function Devices({ live }: { live: number }) {
  const { t, can } = useApp(); const [status, setStatus] = useState(''); const [dlg, setDlg] = useState<any>(null); const act = useAct();
  const s = useLoad<any>(`/devices${qs({ status, limit: 200 })}`, [live]); const staff = useLoad<any>('/staff?limit=200');
  return <Page title={t('nav.devices')}>
    <div className="filters"><div className="field"><label htmlFor="df-s">{t('common.status')}</label><select id="df-s" value={status} onChange={(e: any) => setStatus(e.target.value)}><option value="">{t('common.all')}</option>{['pending_approval', 'active', 'revoked'].map((x) => <option key={x} value={x}>{t(`dev.${x}`)}</option>)}</select></div></div>
    <Async s={s}><Table caption={t('nav.devices')} rows={s.data?.items ?? []} cols={[{ key: 's', label: t('common.staff'), render: (r) => staff.data?.items.find((x: any) => x.id === r.staffMemberId)?.displayName ?? '—' }, { key: 'model', label: 'Model', render: (r) => `${r.platform} ${r.osVersion} · ${r.model ?? ''}` }, { key: 'appVersion', label: t('dev.appVersion'), render: (r) => <span className="mono">{r.appVersion}</span> }, { key: 'status', label: t('common.status'), render: (r) => <Chip value={r.status} ns="dev" /> },
      { key: 'seen', label: t('dev.lastSeen'), render: (r) => <When at={r.lastSeenAt} /> }, { key: 'hb', label: t('dev.health'), render: (r) => r.lastHeartbeat ? <span className="small">{r.lastHeartbeat.battery ?? '—'}% · {r.lastHeartbeat.network ?? '—'} · {r.lastHeartbeat.permissions?.location ?? '—'}{r.lastHeartbeat.bgRestricted ? ' · bg-restricted' : ''}{(r.lastHeartbeat.signals ?? []).length ? ` · ⚑ ${r.lastHeartbeat.signals.join(',')}` : ''}</span> : '—' },
      { key: 'a', label: t('common.actions'), render: (r) => can('device.manage') ? <span className="row">{r.status === 'pending_approval' && <button className="link" onClick={() => void act(() => post(`/devices/${r.id}/approve`).then(() => s.reload()))}>{t('dev.approve')}</button>}{r.status !== 'revoked' && <button className="link" onClick={() => setDlg(r)}>{t('dev.revoke')}</button>}</span> : null }]} /></Async>
    {dlg && <ReasonModal danger title={t('dev.revoke')} onClose={() => setDlg(null)} onSubmit={async (v) => { await post(`/devices/${dlg.id}/revoke`, v); setDlg(null); s.reload(); }} />}
  </Page>;
}

export function Organisation() {
  const { t, can } = useApp(); const units = useLoad<any>('/units'); const teams = useLoad<any>('/teams'); const staff = useLoad<any>(can('staff.read') ? '/staff?status=active&limit=200' : null); const [dlg, setDlg] = useState<any>(null);
  const items: any[] = units.data?.items ?? [];
  const tree = (parent: string | null): any => <ul className="tree">{items.filter((u) => u.parentId === parent && u.status === 'active').map((u) => <li key={u.id}><b>{u.name}</b> <span className="muted small">{u.type}{u.code ? ` · ${u.code}` : ''}</span>
    {can('unit.create') && <><button className="link" onClick={() => setDlg({ kind: 'add', parentId: u.id })}>+</button>{u.parentId && <button className="link" onClick={() => setDlg({ kind: 'move', u })}>{t('org.move')}</button>}</>}{tree(u.id)}</li>)}</ul>;
  return <Page title={t('nav.organisation')} actions={can('team.manage') && <button onClick={() => setDlg({ kind: 'team' })}>{t('org.addTeam')}</button>}>
    <div className="grid two"><div className="card"><h2>{t('org.units')}</h2><Async s={units}>{tree(items.find((u) => !u.parentId)?.parentId ?? null)}</Async></div>
      <div className="card"><h2>{t('org.teams')}</h2><Async s={teams}><Table caption={t('org.teams')} rows={teams.data?.items ?? []} cols={[{ key: 'name', label: t('common.name') }, { key: 'u', label: t('common.unit'), render: (r) => items.find((u) => u.id === r.unitId)?.name }, { key: 'n', label: t('nav.staff'), render: (r) => <Num n={r.staffMemberIds.length} /> }, { key: 'a', label: '', render: (r) => can('team.manage') ? <button className="link" onClick={() => setDlg({ kind: 'members', team: r })}>{t('common.edit')}</button> : null }]} /></Async></div></div>
    {dlg?.kind === 'add' && <FormModal title={t('org.addUnit')} onClose={() => setDlg(null)} fields={[{ name: 'name', label: t('common.name'), required: true }, { name: 'type', label: t('org.unitType'), required: true }, { name: 'code', label: t('org.code'), ltr: true }]} onSubmit={async (v) => { await post('/units', { ...v, parentId: dlg.parentId }); setDlg(null); units.reload(); }} />}
    {dlg?.kind === 'move' && <ReasonModal title={`${t('org.move')}: ${dlg.u.name}`} onClose={() => setDlg(null)} extra={[{ name: 'newParentId', label: t('org.newParent'), type: 'select', required: true, options: unitOptions(items.filter((u) => u.id !== dlg.u.id && !u.ancestorIds.includes(dlg.u.id))) }]} onSubmit={async (v) => { await post(`/units/${dlg.u.id}/move`, v); setDlg(null); units.reload(); }} />}
    {dlg?.kind === 'team' && <FormModal title={t('org.addTeam')} onClose={() => setDlg(null)} fields={[{ name: 'name', label: t('common.name'), required: true }, { name: 'unitId', label: t('common.unit'), type: 'select', required: true, options: unitOptions(items) }]} onSubmit={async (v) => { await post('/teams', v); setDlg(null); teams.reload(); }} />}
    {dlg?.kind === 'members' && <TeamMembers team={dlg.team} staff={staff.data?.items ?? []} onClose={() => { setDlg(null); teams.reload(); }} />}
  </Page>;
}
function TeamMembers({ team, staff, onClose }: { team: any; staff: any[]; onClose(): void }) {
  const { t } = useApp(); const [ids, setIds] = useState<string[]>(team.staffMemberIds); const act = useAct();
  return <Modal title={team.name} onClose={onClose}><div style={{ maxHeight: 360, overflow: 'auto' }}>{staff.map((x) => <div className="field inline" key={x.id}><input type="checkbox" id={`tm-${x.id}`} checked={ids.includes(x.id)} onChange={(e: any) => setIds(e.target.checked ? [...ids, x.id] : ids.filter((i) => i !== x.id))} /><label htmlFor={`tm-${x.id}`}>{x.displayName} <span className="mono muted">{x.employeeCode}</span></label></div>)}</div>
    <div className="row end"><button onClick={onClose}>{t('common.cancel')}</button><button className="primary" onClick={() => void act(() => put(`/teams/${team.id}/members`, { staffMemberIds: ids }).then(onClose))}>{t('common.save')}</button></div></Modal>;
}

export function Sites() {
  const { t, can } = useApp(); const posts = useLoad<any>('/posts?limit=200&status=active'); const units = useLoad<any>('/units'); const [sel, setSel] = useState<string | null>(null); const [dlg, setDlg] = useState<any>(null); const act = useAct();
  const fences = useLoad<any>(sel ? `/geofences?postId=${sel}` : null); const cps = useLoad<any>(sel ? `/checkpoints?postId=${sel}` : null);
  const cur = posts.data?.items.find((p: any) => p.id === sel);
  return <Page title={t('nav.sites')} actions={can('post.create') && <button className="primary" onClick={() => setDlg({ kind: 'post' })}>{t('org.addPost')}</button>}>
    <div className="grid two"><Async s={posts}><Table caption={t('org.posts')} rows={posts.data?.items ?? []} selected={sel} onRow={(r) => setSel(r.id)} cols={[{ key: 'name', label: t('common.name') }, { key: 'u', label: t('common.unit'), render: (r) => units.data?.items.find((u: any) => u.id === r.unitId)?.name }, { key: 'address', label: t('org.address') }, { key: 'timezone', label: t('plat.timezone') }]} /></Async>
      {cur && <div className="card"><h2>{cur.name}</h2><p className="small">{cur.instructions}</p>
        <h3>{t('site.geofences')} {can('geofence.manage') && <button className="link" onClick={() => setDlg({ kind: 'fence' })}>+</button>}</h3>
        <Async s={fences}><Table caption={t('site.geofences')} rows={fences.data?.items ?? []} cols={[{ key: 'name', label: t('common.name') }, { key: 'g', label: t('site.geometry'), render: (r) => r.geometry.shape === 'circle' ? `○ ${r.geometry.radiusM} m` : `▱ ${r.geometry.ring.length}` }, { key: 'v', label: t('common.version'), render: (r) => <Num n={r.version} /> }, { key: 'req', label: t('site.required'), render: (r) => (r.requiredDuringDuty ? '✓' : '—') }]} /></Async>
        <h3 style={{ marginTop: 12 }}>{t('site.checkpoints')} {can('checkpoint.manage') && <button className="link" onClick={() => setDlg({ kind: 'cp' })}>+</button>}</h3>
        <Async s={cps}><Table caption={t('site.checkpoints')} rows={cps.data?.items ?? []} cols={[{ key: 'name', label: t('common.name') }, { key: 'method', label: t('site.method') }, { key: 'q', label: t('site.qr'), render: (r) => r.qrPayload ? <span className="mono small">{r.qrPayload}</span> : '—' }, { key: 'rot', label: '⟳', render: (r) => (r.rotating ? `${r.rotating.periodSec}s` : '—') },
          { key: 'a', label: '', render: (r) => can('checkpoint.manage') ? <button className="link" onClick={() => setDlg({ kind: 'reissue', cp: r })}>{t('site.reissue')}</button> : null }]} /></Async></div>}</div>
    {dlg?.kind === 'post' && <FormModal title={t('org.addPost')} onClose={() => setDlg(null)} fields={[{ name: 'name', label: t('common.name'), required: true }, { name: 'unitId', label: t('common.unit'), type: 'select', required: true, options: unitOptions(units.data?.items) }, { name: 'address', label: t('org.address') }, { name: 'lat', label: t('org.lat'), type: 'number', ltr: true }, { name: 'lon', label: t('org.lon'), type: 'number', ltr: true }, { name: 'instructions', label: t('org.instructions'), type: 'textarea' }]}
      onSubmit={async (v) => { const { lat, lon, ...rest } = v; const r = await post('/posts', { ...rest, ...(lat !== undefined && lon !== undefined ? { location: { lat, lon } } : {}) }); setDlg(null); posts.reload(); setSel(r.id); }} />}
    {dlg?.kind === 'fence' && <FormModal title={t('site.addGeofence')} onClose={() => setDlg(null)} initial={{ lat: cur.location?.lat, lon: cur.location?.lon, radiusM: 100 }} fields={[{ name: 'name', label: t('common.name'), required: true }, { name: 'lat', label: t('org.lat'), type: 'number', required: true, ltr: true }, { name: 'lon', label: t('org.lon'), type: 'number', required: true, ltr: true }, { name: 'radiusM', label: t('site.radius'), type: 'number', required: true }, { name: 'requiredDuringDuty', label: t('site.required'), type: 'checkbox' }]}
      onSubmit={async (v) => { await post('/geofences', { postId: sel, name: v.name, geometry: { shape: 'circle', center: { lat: v.lat, lon: v.lon }, radiusM: v.radiusM }, requiredDuringDuty: v.requiredDuringDuty }); setDlg(null); fences.reload(); }} />}
    {dlg?.kind === 'cp' && <FormModal title={t('site.addCheckpoint')} onClose={() => setDlg(null)} fields={[{ name: 'name', label: t('common.name'), required: true }, { name: 'method', label: t('site.method'), type: 'select', required: true, options: [{ value: 'qr', label: 'QR' }, { value: 'nfc', label: 'NFC' }, { value: 'geo', label: 'Geofence' }] }, { name: 'instructions', label: t('org.instructions'), type: 'textarea' }, { name: 'rotatingPeriodSec', label: t('site.rotating'), type: 'number' }]}
      onSubmit={async (v) => { await post('/checkpoints', { postId: sel, ...v }); setDlg(null); cps.reload(); }} />}
    {dlg?.kind === 'reissue' && <ReasonModal title={t('site.reissue')} onClose={() => setDlg(null)} onSubmit={async (v) => { await act(() => post(`/checkpoints/${dlg.cp.id}/reissue`, v)); setDlg(null); cps.reload(); }} />}
  </Page>;
}

export function Roles() {
  const { t, can } = useApp(); const roles = useLoad<any>('/roles'); const users = useLoad<any>(can('membership.read') ? '/users?limit=200' : null); const [sel, setSel] = useState<string | null>(null); const [dlg, setDlg] = useState<any>(null); const act = useAct();
  const cur = roles.data?.items.find((r: any) => r.id === sel);
  return <Page title={t('nav.roles')}>
    <div className="grid two"><Async s={roles}><Table caption={t('nav.roles')} rows={roles.data?.items ?? []} selected={sel} onRow={(r) => setSel(r.id)} cols={[{ key: 'name', label: t('common.name') }, { key: 'd', label: '', render: (r) => <span className="chip plain">{r.isDefault ? t('role.default') : t('role.custom')}</span> }, { key: 'n', label: t('role.permissions'), render: (r) => <Num n={r.permissionKeys.length} /> }]} /></Async>
      {cur && <div className="card"><h2>{cur.name}</h2>{can('role.create') && <button onClick={() => void act(() => post('/roles', { name: `${cur.name} (copy)`, clonedFrom: cur.id }).then(() => roles.reload()))}>{t('role.clone')}</button>}
        <ul className="small mono" style={{ columns: 2 }}>{cur.permissionKeys.map((k: string) => <li key={k}>{k}</li>)}</ul></div>}</div>
    {users.data && <div className="card"><h2>{t('role.members')}</h2><Table caption={t('role.members')} rows={users.data.items} cols={[{ key: 'username', label: t('staff.username'), render: (r) => <span className="mono">{r.username}</span> }, { key: 'r', label: t('staff.role'), render: (r) => (roles.data?.items ?? []).filter((x: any) => r.roleIds.includes(x.id)).map((x: any) => x.name).join(', ') }, { key: 's', label: t('role.scope'), render: (r) => (r.scopeUnitIds.includes('*') ? t('role.wholeOrg') : <Num n={r.scopeUnitIds.length} />) },
      { key: 'mfa', label: t('role.mfa'), render: (r) => (r.mfaEnabled ? '✓' : '—') }, { key: 'last', label: 'Last sign-in', render: (r) => <When at={r.lastLoginAt} /> },
      { key: 'a', label: t('common.actions'), render: (r) => <span className="row">{r.locked && <><Chip value="suspended" ns="staff" /><button className="link" onClick={() => void act(() => post(`/users/${r.id}/unlock`).then(() => users.reload()))}>{t('role.unlock')}</button></>}{r.mfaEnabled && can('user.mfa.reset') && <button className="link" onClick={() => setDlg({ kind: 'mfa', u: r })}>{t('role.resetMfa')}</button>}{can('session.revoke') && <button className="link" onClick={() => setDlg({ kind: 'sessions', u: r })}>{t('role.sessions')}</button>}</span> }]} /></div>}
    {dlg?.kind === 'mfa' && <ReasonModal danger title={t('role.resetMfa')} onClose={() => setDlg(null)} onSubmit={async (v) => { await post(`/users/${dlg.u.id}/mfa/reset`, v); setDlg(null); users.reload(); }} />}
    {dlg?.kind === 'sessions' && <Sessions userId={dlg.u.id} onClose={() => setDlg(null)} />}
  </Page>;
}
function Sessions({ userId, onClose }: { userId: string; onClose(): void }) {
  const { t } = useApp(); const s = useLoad<any>(`/auth/sessions?userId=${userId}`); const act = useAct();
  return <Modal title={t('role.sessions')} onClose={onClose} wide><Async s={s}><Table caption={t('role.sessions')} rows={s.data?.items ?? []} cols={[{ key: 'createdAt', label: 'Created', render: (r) => <When at={r.createdAt} /> }, { key: 'lastUsedAt', label: 'Last used', render: (r) => <When at={r.lastUsedAt} /> }, { key: 'deviceId', label: t('nav.devices'), render: (r) => (r.deviceId ? 'mobile' : 'web') }, { key: 'userAgent', label: '', render: (r) => <span className="small">{r.userAgent}</span> },
    { key: 'a', label: '', render: (r) => <button className="link" onClick={() => void act(() => del(`/auth/sessions/${r.id}`).then(() => s.reload()))}>{t('role.revoke')}</button> }]} /></Async><div className="row end"><button onClick={onClose}>{t('common.close')}</button></div></Modal>;
}

export function Settings() {
  const { t, can, toast } = useApp(); const [tab, setTab] = useState('policies');
  const st = useLoad<any>('/tenant/settings'); const rules = useLoad<any>(tab === 'alerts' ? '/alert-rules' : null); const labels = useLoad<any>(tab === 'labels' ? '/tenant/labels' : null);
  const notices = useLoad<any>(tab === 'notice' ? '/privacy/notices' : null); const ret = useLoad<any>(tab === 'retention' ? '/retention/policies' : null); const ints = useLoad<any>(tab === 'integrations' && can('integration.read') ? '/tenant/integrations' : null); const cats = useLoad<any>(tab === 'catalogues' ? '/catalogues' : null);
  const [dry, setDry] = useState<any>(null); const [rule, setRule] = useState<any>(null); const act = useAct(); const edit = can('settings.update');
  const e = st.data?.effective;
  const save = async (settings: unknown) => { const r = await put('/tenant/settings', { version: st.data.version, settings: deepMergeObj(st.data.overrides, settings) }); toast(t('set.saved', { version: r.version })); st.reload(); };
  const policyFields: [string, string, FieldDef['type'], string[]?][] = [['duty.earlyMin', 'set.earlyMin', 'number'], ['duty.lateMin', 'set.lateMin', 'number'], ['duty.overlapPolicy', 'set.overlap', 'select', ['block', 'warn', 'allow']], ['duty.missedCheckOut', 'set.missedCheckOut', 'select', ['flag', 'auto_close', 'remain_open']], ['duty.geofenceStart', 'set.geofenceStart', 'select', ['off', 'warn', 'require']],
    ['location.liveSec', 'set.liveSec', 'number'], ['location.recentSec', 'set.recentSec', 'number'], ['location.movingSec', 'set.movingSec', 'number'], ['location.stationarySec', 'set.stationarySec', 'number'], ['sos.holdSec', 'set.holdSec', 'number'], ['sos.fallbackSec', 'set.fallbackSec', 'number'], ['devices.maxActivePerStaff', 'set.maxDevices', 'number'], ['devices.minAppVersion', 'set.minAppVersion', 'text'], ['map.tileUrl', 'set.tileUrl', 'text'], ['map.attribution', 'Map attribution', 'text']];
  const getp = (o: any, p: string) => p.split('.').reduce((x, k) => x?.[k], o);
  return <Page title={t('nav.settings')} sub={t('set.defaultsNote')} actions={st.data && <span className="small muted">{t('common.version')} <Num n={st.data.version} /></span>}>
    <Tabs value={tab} onChange={setTab} tabs={[{ id: 'policies', label: t('set.policies') }, { id: 'alerts', label: t('set.alertRules') }, { id: 'labels', label: t('set.labels') }, { id: 'catalogues', label: 'Catalogues' }, { id: 'notice', label: t('set.notice') }, { id: 'retention', label: t('set.retention') }, { id: 'integrations', label: t('set.integrations') }]} />
    {tab === 'policies' && <Async s={st}>{e && <div className="card" style={{ maxWidth: 640 }}><Form key={st.data.version} submit={t('common.save')} initial={Object.fromEntries(policyFields.map(([p]) => [p, getp(e, p)]))}
      fields={policyFields.map(([p, l, type, opts]) => ({ name: p, label: t(l), type, options: opts?.map((o) => ({ value: o, label: o.replace('_', ' ') })), ltr: type !== 'select' }))}
      onSubmit={async (v) => { const out: any = {}; for (const [p, val] of Object.entries(v)) { if (val === getp(e, p)) continue; const ks = p.split('.'); (out[ks[0]!] ??= {})[ks[1]!] = val; } if (!edit) return; await save(out); }} /></div>}</Async>}
    {tab === 'alerts' && <Async s={rules}><Table caption={t('set.alertRules')} rows={rules.data?.items ?? []} cols={[{ key: 'type', label: t('common.type'), render: (r) => t(`alert.${r.type}`) }, { key: 'enabled', label: t('set.enabled'), render: (r) => (r.enabled ? '✓' : '—') }, { key: 'severity', label: 'Severity', render: (r) => <Chip value={r.severity} ns="sev" /> }, { key: 'th', label: t('set.thresholds'), render: (r) => <span className="mono small">{JSON.stringify(r.thresholds)}</span> }, { key: 'rec', label: t('set.recipients'), render: (r) => r.recipientGroups.join(', ') }, { key: 'a', label: '', render: (r) => can('alertrule.update') ? <button className="link" onClick={() => setRule(r)}>{t('common.edit')}</button> : null }]} /></Async>}
    {rule && <FormModal title={t(`alert.${rule.type}`)} onClose={() => setRule(null)} initial={{ enabled: rule.enabled, severity: rule.severity, thresholds: JSON.stringify(rule.thresholds), recipients: rule.recipientGroups.join(',') }} fields={[{ name: 'enabled', label: t('set.enabled'), type: 'checkbox' }, { name: 'severity', label: 'Severity', type: 'select', options: ['low', 'medium', 'high', 'critical'].map((x) => ({ value: x, label: t(`sev.${x}`) })) }, { name: 'thresholds', label: t('set.thresholds'), help: 'JSON, e.g. {"afterMin":15}', ltr: true }, { name: 'recipients', label: t('set.recipients'), help: 'owner, admin, commander, supervisor, dispatcher', ltr: true }]}
      onSubmit={async (v) => { await put(`/alert-rules/${rule.id}`, { version: rule.version, enabled: v.enabled, severity: v.severity, thresholds: JSON.parse(v.thresholds), recipientGroups: String(v.recipients).split(',').map((x) => x.trim()).filter(Boolean), ...(rule.escalationPolicyId ? { escalationPolicyId: rule.escalationPolicyId } : {}) }); setRule(null); rules.reload(); }} />}
    {tab === 'labels' && <Async s={labels}>{labels.data && <div className="card" style={{ maxWidth: 640 }}><Form submit={t('common.save')} initial={{ postEn: labels.data.labels.post?.en, postAr: labels.data.labels.post?.ar, fsEn: labels.data.labels.fieldStaff?.en, fsAr: labels.data.labels.fieldStaff?.ar }}
      fields={[{ name: 'postEn', label: `${t('common.post')} (EN)` }, { name: 'postAr', label: `${t('common.post')} (AR)` }, { name: 'fsEn', label: 'Field staff (EN)' }, { name: 'fsAr', label: 'Field staff (AR)' }]}
      onSubmit={async (v) => { await put('/tenant/labels', { version: labels.data.version, labels: { ...labels.data.labels, post: { en: v.postEn, ar: v.postAr }, fieldStaff: { en: v.fsEn, ar: v.fsAr } } }); labels.reload(); toast('✓'); }} /></div>}</Async>}
    {tab === 'catalogues' && <Async s={cats}><Table caption="Catalogues" rows={cats.data?.items ?? []} cols={[{ key: 'kind', label: t('common.type') }, { key: 'key', label: 'Key', render: (r) => <span className="mono">{r.key}</span> }, { key: 'en', label: 'EN', render: (r) => r.labels.en }, { key: 'ar', label: 'AR', render: (r) => <span dir="rtl">{r.labels.ar}</span> }, { key: 'arch', label: '', render: (r) => can('catalogue.manage') ? <button className="link" onClick={() => void act(() => patch(`/catalogues/${r.id}`, { archived: !r.archived }).then(() => cats.reload()))}>{r.archived ? 'Restore' : 'Archive'}</button> : null }]} />
      {can('catalogue.manage') && <div className="card" style={{ marginTop: 10, maxWidth: 520 }}><Form submit={t('common.create')} fields={[{ name: 'kind', label: t('common.type'), type: 'select', required: true, options: ['incidentType', 'dutyType', 'exceptionReason', 'resolutionCode'].map((x) => ({ value: x, label: x })) }, { name: 'key', label: 'Key', required: true, ltr: true }, { name: 'en', label: 'EN', required: true }, { name: 'ar', label: 'AR', required: true }]} onSubmit={async (v) => { await post('/catalogues', { kind: v.kind, key: v.key, labels: { en: v.en, ar: v.ar } }); cats.reload(); }} /></div>}</Async>}
    {tab === 'notice' && <Async s={notices}><Table caption={t('set.notice')} rowKey="version" rows={notices.data?.items ?? []} cols={[{ key: 'version', label: t('common.version') }, { key: 'effectiveFrom', label: t('common.from'), render: (r) => <When at={r.effectiveFrom} /> }, { key: 'acknowledgements', label: t('plan.ack'), render: (r) => <Num n={r.acknowledgements} /> }]} />
      {can('privacy.notice.manage') && <div className="card" style={{ marginTop: 10 }}><p className="notice">{t('set.noticeHelp')}</p><Form submit={t('set.publishNotice')} initial={{ en: notices.data?.items[0]?.texts.en, ar: notices.data?.items[0]?.texts.ar }} fields={[{ name: 'en', label: `${t('set.noticeText')} (EN)`, type: 'textarea', required: true }, { name: 'ar', label: `${t('set.noticeText')} (AR)`, type: 'textarea', required: true }]} onSubmit={async (v) => { await post('/privacy/notices', { texts: { en: v.en, ar: v.ar } }); notices.reload(); }} /></div>}</Async>}
    {tab === 'retention' && <Async s={ret}>{ret.data && <><div className="card"><Table caption={t('set.retention')} rowKey="k" rows={Object.entries(ret.data.retentionDays).map(([k, d]) => ({ k, d, cols: ret.data.classes[k].join(', '), dry: dry?.result?.[k] }))} cols={[{ key: 'k', label: t('common.type') }, { key: 'd', label: t('set.retentionDays'), render: (r) => <Num n={r.d as number} /> }, { key: 'cols', label: '', render: (r) => <span className="small mono">{r.cols}</span> }, { key: 'dry', label: t('set.eligible'), render: (r) => (r.dry ? <><Num n={r.dry.eligible} /> · {t('set.held')} <Num n={r.dry.skippedForLegalHold} /> · {t('set.deleted')} <Num n={r.dry.deleted} /></> : '—') }]} />
      {can('retention.manage') && <div className="row" style={{ marginTop: 10 }}><button onClick={() => void act(async () => setDry(await post('/retention/runs', { dryRun: true })))}>{t('set.dryRun')}</button><button className="danger" disabled={!dry?.dryRun} onClick={() => void act(async () => { setDry(await post('/retention/runs', { dryRun: false })); ret.reload(); })}>{t('set.runNow')}</button></div>}</div>
      <div className="card"><h2>Runs</h2><Table caption="Runs" rows={ret.data.runs} cols={[{ key: 'startedAt', label: t('common.time'), render: (r) => <When at={r.startedAt} /> }, { key: 'dryRun', label: 'Dry run', render: (r) => (r.dryRun ? '✓' : '—') }]} /></div></>}</Async>}
    {tab === 'integrations' && <Async s={ints}><Table caption={t('set.integrations')} rowKey="kind" rows={ints.data?.items ?? []} cols={[{ key: 'kind', label: t('common.type') }, { key: 'enabled', label: t('set.enabled'), render: (r) => (r.enabled ? '✓' : '—') }, { key: 'configured', label: '', render: (r) => (r.configured ? t('set.configured') : t('set.notConfigured')) }, { key: 'adapter', label: '', render: (r) => (r.adapterAvailable ? '' : t('set.adapterMissing')) }, { key: 'last', label: 'Last result', render: (r) => r.lastDeliveryResult ?? '—' }]} /></Async>}
  </Page>;
}
function deepMergeObj(a: any, b: any): any { if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) return b ?? a; const o = { ...a }; for (const [k, v] of Object.entries(b)) o[k] = deepMergeObj(a[k], v); return o; }

export function Privacy() {
  const { t, can } = useApp(); const holds = useLoad<any>(can('legalhold.manage') ? '/tenant/legal-holds' : null); const staff = useLoad<any>('/staff?limit=200'); const [dlg, setDlg] = useState<any>(null);
  return <Page title={t('nav.privacy')}>
    {can('legalhold.manage') && <div className="card"><div className="row" style={{ justifyContent: 'space-between' }}><h2>{t('prv.holds')}</h2><button onClick={() => setDlg({ kind: 'hold' })}>{t('prv.placeHold')}</button></div>
      <Async s={holds}><Table caption={t('prv.holds')} rows={holds.data?.items ?? []} cols={[{ key: 's', label: t('prv.holdScope'), render: (r) => r.scope.kind === 'tenant' ? t('prv.wholeOrg') : `${r.scope.kind}: ${staff.data?.items.find((x: any) => x.id === r.scope.id)?.displayName ?? r.scope.id}` }, { key: 'reason', label: t('common.reason') }, { key: 'placedAt', label: t('common.time'), render: (r) => <When at={r.placedAt} /> }, { key: 'rel', label: '', render: (r) => (r.releasedAt ? <When at={r.releasedAt} /> : <button className="link" onClick={() => setDlg({ kind: 'release', h: r })}>{t('prv.release')}</button>) }]} /></Async></div>}
    <div className="card"><h2>{t('prv.subject')}</h2><p className="muted">{t('nav.staff')} → {t('prv.exportSubject')} / {t('prv.deleteSubject')}</p></div>
    {dlg?.kind === 'hold' && <ReasonModal title={t('prv.placeHold')} onClose={() => setDlg(null)} extra={[{ name: 'target', label: t('prv.holdScope'), type: 'select', required: true, options: [{ value: 'tenant', label: t('prv.wholeOrg') }, ...(staff.data?.items ?? []).map((x: any) => ({ value: x.id, label: x.displayName }))] }]} onSubmit={async (v) => { await post('/tenant/legal-holds', { scope: v.target === 'tenant' ? { kind: 'tenant' } : { kind: 'staff', id: v.target }, reason: v.reason }); setDlg(null); holds.reload(); }} />}
    {dlg?.kind === 'release' && <ReasonModal title={t('prv.release')} onClose={() => setDlg(null)} onSubmit={async (v) => { await post(`/tenant/legal-holds/${dlg.h.id}/release`, v); setDlg(null); holds.reload(); }} />}
  </Page>;
}

export function Audit() {
  const { t } = useApp(); const [f, setF] = useState({ action: '', outcome: '', resourceType: '' }); const [cursor, setCursor] = useState<string[]>([]); const [sel, setSel] = useState<any>(null); const [v, setV] = useState<any>(null); const act = useAct();
  const s = useLoad<any>(`/audit/events${qs({ ...f, limit: 50, cursor: cursor[cursor.length - 1] })}`);
  return <Page title={t('nav.audit')} actions={<button onClick={() => void act(async () => setV(await get('/audit/verify')))}>{t('aud.verify')}</button>}>
    {v && <div className={`notice ${v.ok ? '' : 'danger'}`} role="status">{v.ok ? t('aud.verified', { count: v.count }) : t('aud.broken', { seq: v.brokenAtSeq })}</div>}
    <div className="filters"><div className="field"><label htmlFor="au-a">{t('aud.action')}</label><input id="au-a" dir="ltr" value={f.action} onChange={(e: any) => { setCursor([]); setF({ ...f, action: e.target.value }); }} /></div>
      <div className="field"><label htmlFor="au-r">{t('aud.resource')}</label><input id="au-r" dir="ltr" value={f.resourceType} onChange={(e: any) => { setCursor([]); setF({ ...f, resourceType: e.target.value }); }} /></div>
      <div className="field"><label htmlFor="au-o">{t('aud.outcome')}</label><select id="au-o" value={f.outcome} onChange={(e: any) => { setCursor([]); setF({ ...f, outcome: e.target.value }); }}><option value="">{t('common.all')}</option>{['success', 'denied', 'failed'].map((x) => <option key={x} value={x}>{t(`aud.${x}`)}</option>)}</select></div></div>
    <Async s={s}><Table caption={t('nav.audit')} rows={s.data?.items ?? []} onRow={setSel} cols={[{ key: 'seq', label: '#', render: (r) => <Num n={r.seq} /> }, { key: 'occurredAt', label: t('common.time'), render: (r) => <When at={r.occurredAt} /> }, { key: 'action', label: t('aud.action'), render: (r) => <span className="mono">{r.action}</span> }, { key: 'actor', label: t('aud.actor'), render: (r) => <span className="small">{r.actor.type} · {(r.actor.roles ?? []).join(',')}</span> }, { key: 'res', label: t('aud.resource'), render: (r) => <span className="small mono">{r.resourceType}{r.resourceId ? `/${r.resourceId.slice(-6)}` : ''}</span> }, { key: 'outcome', label: t('aud.outcome'), render: (r) => <Chip value={r.outcome} ns="aud" /> }, { key: 'reason', label: t('common.reason') }]} />
      <div className="row" style={{ marginTop: 8 }}>{cursor.length > 0 && <button onClick={() => setCursor(cursor.slice(0, -1))}>{t('common.back')}</button>}{s.data?.nextCursor && <button onClick={() => setCursor([...cursor, s.data.nextCursor])}>{t('common.next')}</button>}</div></Async>
    {sel && <Modal title={sel.action} onClose={() => setSel(null)} wide><pre className="small mono" style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify(sel, null, 2)}</pre><div className="row end"><button onClick={() => setSel(null)}>{t('common.close')}</button></div></Modal>}
  </Page>;
}

export function Account() {
  const { t, can, me } = useApp(); const sub = useLoad<any>('/tenant/subscription'); const usage = useLoad<any>(can('settings.read') ? '/tenant/usage' : null); const grants = useLoad<any>(can('support.grant.manage') ? '/tenant/support-grants' : null); const dels = useLoad<any>(can('tenant.delete') ? '/tenant/deletion-requests' : null);
  const [dlg, setDlg] = useState<string | null>(null); const act = useAct();
  const u = usage.data; const pending = dels.data?.items.find((x: any) => x.state === 'pending');
  return <Page title={t('nav.account')}>
    <div className="grid two"><div className="card"><h2>{t('acc.plan')}: {sub.data?.plan?.name}</h2><p className="small muted">{t('acc.noBilling')}</p>
      {u && <Table caption={t('acc.usage')} rowKey="k" rows={[['activeStaff', u.usage.activeStaff], ['posts', u.usage.posts], ['devices', u.usage.devices], ['storage', Math.round(u.usage.storageBytes / 1048576)]].map(([k, n]) => ({ k, n, l: u.limits[k === 'storage' ? 'storageGb' : (k as string)] }))} cols={[{ key: 'k', label: '', render: (r) => t(`acc.${r.k === 'storage' ? 'storage' : r.k}`) }, { key: 'n', label: t('acc.usage'), render: (r) => <><Num n={r.n} />{r.k === 'storage' ? ' MB' : ''}</> }, { key: 'l', label: t('acc.limit'), render: (r) => <><Num n={r.l} />{r.k === 'storage' ? ' GB' : ''}</> }]} />}
      {u && <AsOf at={u.asOf} />}</div>
      {grants.data && <div className="card"><h2>{t('acc.support')}</h2><p className="small muted">{t('acc.supportHelp')}</p><Table caption={t('acc.support')} rows={grants.data.items} cols={[{ key: 'reason', label: t('common.reason') }, { key: 'scope', label: t('role.permissions'), render: (r) => <span className="mono small">{r.scope.join(', ')}</span> }, { key: 'mode', label: t('common.type') }, { key: 'state', label: t('common.status') }, { key: 'exp', label: 'Expires', render: (r) => <When at={r.expiresAt} /> },
        { key: 'a', label: '', render: (r) => <span className="row">{r.state === 'requested' && <><button className="link" onClick={() => void act(() => post(`/tenant/support-grants/${r.id}/approve`, {}).then(() => grants.reload()))}>{t('common.approve')}</button><button className="link" onClick={() => void act(() => post(`/tenant/support-grants/${r.id}/deny`, {}).then(() => grants.reload()))}>{t('common.reject')}</button></>}{r.state === 'approved' && <button className="link" onClick={() => void act(() => post(`/tenant/support-grants/${r.id}/revoke`, {}).then(() => grants.reload()))}>{t('role.revoke')}</button>}</span> }]} /></div>}</div>
    {can('tenant.export') && <div className="card"><h2>{t('acc.export')}</h2><button onClick={() => void act(() => post('/tenant/exports'), t('rep.exportQueued'))}>{t('acc.export')}</button> <a href="#/reports">{t('rep.exports')}</a></div>}
    {can('tenant.delete') && <div className="card"><h2>{t('acc.delete')}</h2><p>{t('acc.deleteHelp', { days: 30 })}</p>{pending ? <><div className="notice danger">Scheduled for <When at={pending.scheduledAt} /></div><button onClick={() => void act(() => del('/tenant/deletion-requests').then(() => location.reload()))}>{t('acc.cancelDeletion')}</button></> : <button className="danger" onClick={() => setDlg('delete')}>{t('acc.delete')}</button>}</div>}
    {dlg === 'delete' && <ReasonModal danger title={t('acc.delete')} onClose={() => setDlg(null)} extra={[{ name: 'confirmSlug', label: `${t('acc.confirmSlug')} (${me.tenant.slug})`, required: true, ltr: true }]} onSubmit={async (v) => { await post('/tenant/deletion-requests', v); setDlg(null); location.reload(); }} />}
  </Page>;
}

export function Platform() {
  const { t } = useApp(); const tenants = useLoad<any>('/platform/tenants'); const health = useLoad<any>('/platform/health'); const plans = useLoad<any>('/platform/plans'); const [dlg, setDlg] = useState<any>(null);
  const signup = useLoad<any>('/platform/auth/signup-options'); // simple local mode: anyone signs up directly, so no invitation codes
  return <Page title={t('nav.platform')} sub={t('plat.metadataOnly')} actions={<>{signup.data?.codeRequired && <button onClick={() => setDlg({ kind: 'invite' })}>{t('plat.invite')}</button>}<button className="primary" onClick={() => setDlg({ kind: 'prov' })}>{t('plat.provision')}</button></>}>
    <Async s={health}>{health.data && <div className="grid k" style={{ marginBottom: 12 }}><div className={`kpi ${health.data.store.ok ? 'ok' : 'danger'}`}><b>{health.data.store.kind}</b><span>{t('plat.store')}</span></div><div className={`kpi ${health.data.queue.dead ? 'danger' : 'ok'}`}><b><Num n={health.data.queue.due} /> / <Num n={health.data.queue.dead} /></b><span>{t('plat.queue')} (due / dead)</span></div><div className="kpi"><b><Num n={health.data.realtime.connections} /></b><span>{t('plat.realtime')}</span></div><div className="kpi warn"><b>{health.data.backup.state}</b><span>{t('plat.backup')}</span></div></div>}</Async>
    <Async s={tenants}><Table caption={t('plat.tenants')} rows={tenants.data?.items ?? []} cols={[{ key: 'name', label: t('common.name') }, { key: 'slug', label: t('plat.slug'), render: (r) => <span className="mono">{r.slug}</span> }, { key: 'status', label: t('common.status'), render: (r) => <Chip value={r.status} ns="staff" /> }, { key: 'planKey', label: t('acc.plan') }, { key: 'u', label: t('acc.usage'), render: (r) => r.usage ? <span className="small">{r.usage.activeStaff} staff · {r.usage.devices} devices · {r.usage.posts} posts</span> : '—' },
      { key: 'a', label: '', render: (r) => r.status === 'deleted' ? null : <span className="row">{['active', 'trial'].includes(r.status) && <button className="link" onClick={() => setDlg({ kind: 'life', action: 'suspend', r })}>{t('plat.suspend')}</button>}{['suspended', 'archived'].includes(r.status) && <button className="link" onClick={() => setDlg({ kind: 'life', action: 'resume', r })}>{t('plat.resume')}</button>}<button className="link" onClick={() => setDlg({ kind: 'plan', r })}>{t('acc.plan')}</button><button className="link" onClick={() => setDlg({ kind: 'grant', r })}>{t('plat.requestAccess')}</button></span> }]} /></Async>
    {dlg?.kind === 'prov' && !dlg.result && <FormModal title={t('plat.provision')} onClose={() => setDlg(null)} initial={{ timezone: 'Asia/Karachi', defaultLocale: 'en', planKey: 'pilot' }} fields={[{ name: 'name', label: t('common.name'), required: true }, { name: 'slug', label: t('plat.slug'), required: true, ltr: true }, { name: 'timezone', label: t('plat.timezone'), required: true, ltr: true }, { name: 'defaultLocale', label: t('common.language'), type: 'select', options: [{ value: 'en', label: 'English' }, { value: 'ar', label: 'العربية' }] }, { name: 'planKey', label: t('acc.plan'), type: 'select', options: (plans.data?.items ?? []).map((p: any) => ({ value: p.key, label: p.name })) }, { name: 'ownerUsername', label: t('plat.ownerUsername'), required: true, ltr: true }, { name: 'ownerName', label: t('plat.ownerName'), required: true }, { name: 'ownerEmail', label: t('auth.email'), type: 'email', ltr: true }]}
      onSubmit={async (v) => { const r = await post('/platform/tenants', { name: v.name, slug: v.slug, timezone: v.timezone, defaultLocale: v.defaultLocale, planKey: v.planKey, owner: { username: v.ownerUsername, displayName: v.ownerName, ...(v.ownerEmail ? { email: v.ownerEmail } : {}) } }, { 'Idempotency-Key': newKey() }); setDlg({ ...dlg, result: r }); tenants.reload(); }} />}
    {dlg?.kind === 'prov' && dlg.result && <Modal title={dlg.result.tenant.name} onClose={() => setDlg(null)}><Secret label={t('auth.activationCode')} value={dlg.result.ownerActivationCode} /><div className="row end"><button onClick={() => setDlg(null)}>{t('common.close')}</button></div></Modal>}
    {dlg?.kind === 'invite' && !dlg.result && <FormModal title={t('plat.invite')} intro={<p className="small">{t('plat.inviteHelp')}</p>} submit={t('common.create')} onClose={() => setDlg(null)}
      fields={[{ name: 'email', label: t('auth.email'), type: 'email', required: true, ltr: true, requiredMessage: t('auth.emailRequired'), validate: (x: string) => (/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(x.trim()) ? null : t('auth.emailInvalid')) }]}
      onSubmit={async (v) => { const r = await post('/platform/invitations', { email: v.email.trim() }); setDlg({ kind: 'invite', result: r }); }} />}
    {dlg?.kind === 'invite' && dlg.result && <Modal title={`${t('plat.invite')}: ${dlg.result.email}`} onClose={() => setDlg(null)}><p className="small">{t('plat.inviteHelp')}</p><Secret label={t('plat.inviteCode')} value={dlg.result.code} /><div className="row end"><button onClick={() => setDlg(null)}>{t('common.close')}</button></div></Modal>}
    {dlg?.kind === 'life' && <ReasonModal danger={dlg.action === 'suspend'} title={`${t(`plat.${dlg.action}`)}: ${dlg.r.name}`} onClose={() => setDlg(null)} onSubmit={async (v) => { await post(`/platform/tenants/${dlg.r.id}/${dlg.action}`, v); setDlg(null); tenants.reload(); }} />}
    {dlg?.kind === 'plan' && <ReasonModal title={t('acc.plan')} onClose={() => setDlg(null)} extra={[{ name: 'planKey', label: t('acc.plan'), type: 'select', required: true, options: (plans.data?.items ?? []).map((p: any) => ({ value: p.key, label: p.name })) }]} onSubmit={async (v) => { await put(`/platform/tenants/${dlg.r.id}/plan`, v); setDlg(null); tenants.reload(); }} />}
    {dlg?.kind === 'grant' && <ReasonModal title={t('plat.requestAccess')} onClose={() => setDlg(null)} extra={[{ name: 'hours', label: 'Hours', type: 'number', required: true }]} onSubmit={async (v) => { await post('/platform/support-grants', { tenantId: dlg.r.id, reason: v.reason, hours: v.hours, scope: ['dashboard.read', 'alert.read', 'incident.read'] }); setDlg(null); }} />}
  </Page>;
}
export { KV };
